"""
code_headers.py — Code generation header templates and generator functions.

Incorporated from archive/appgen/src/oheaders.py.
Provides reusable templates for PgAppForge code generation:
- Import blocks for models, views, APIs, GraphQL
- Model/view/API class body generators
- Column type generators (photo, file, relationship, hybrid property)
- View type generators (list, show, chart, master-detail)
- Mixin generators (audit, model mixins)

Usage in codegen pipeline:
    from pgappforge.cli.generators.code_headers import (
        gen_model_header, gen_view_header, gen_api_header,
        gen_model_body, gen_view_body, gen_api_class,
    )
"""
from __future__ import annotations
from datetime import date
from typing import List, Optional, Dict, Any, AnyStr
from dataclasses import field as Field
def snake_to_camel(s: str) -> str:
    """Convert snake_case to camelCase."""
    parts = s.split('_')
    return parts[0] + ''.join(w.title() for w in parts[1:])

def snake_to_pascal(s: str) -> str:
    """Convert snake_case to PascalCase."""
    return ''.join(w.title() for w in s.split('_'))

# Constants
CURRENT_YEAR = date.today().year
